// Kapa Premium server, single file for Cloudflare's online editor. Generated by server/bundle.mjs; edit worker.js and strategy.js instead.

/**
 * KAPA AI Premium strategies. This file runs only on the server: the website never
 * receives these rules, it only receives the next trade to place.
 *
 * The values below are defaults. Because this source code is public, the real values can be
 * kept private in the PREMIUM_RULES secret (JSON: { "presets": {...}, "bots": {...} }),
 * which replaces them. See server/README.md.
 */

const DEFAULT_PRESETS = {
    pegasus: { barrier: 1, recovery: 5, recMode: 'mult', martingale: 2.2, maxLosses: 4 },
    martingale: { barrier: 2, recovery: 4, recMode: 'mult', martingale: 2.2, maxLosses: 5 },
    recover: { barrier: 1, recovery: 5, recMode: 'recover', martingale: 1, maxLosses: 4 },
};

const SYMBOLS = ['R_10', 'R_25', 'R_50', 'R_75', 'R_100', '1HZ10V', '1HZ25V', '1HZ50V', '1HZ75V', '1HZ100V'];

/** Settings of the Premium bots in the Free Bot library; only members receive them. */
const DEFAULT_BOTS = {
    'under7-dalembert': { xml: 'dalembert', symbol: 'R_75', tradetype: 'overunder', type: 'DIGITUNDER', prediction: 7, stake: 1, unit: 1, profit: 5, loss: 25, duration: 1 },
    'odd-oscars': { xml: 'oscars_grind', symbol: 'R_25', tradetype: 'evenodd', type: 'DIGITODD', stake: 1, unit: 1, profit: 5, loss: 25, duration: 1 },
};

const PRESET_KEYS = ['pegasus', 'martingale', 'recover'];
const BOT_KEYS = ['under7-dalembert', 'odd-oscars'];

/** Premium rules for this deployment: PREMIUM_RULES when it is set and valid, otherwise the defaults. */
const loadRules = env => {
    let custom = {};
    if (env?.PREMIUM_RULES) {
        try {
            custom = JSON.parse(env.PREMIUM_RULES);
        } catch {
            throw new Error('PREMIUM_RULES is not valid JSON');
        }
    }
    const presets = { ...DEFAULT_PRESETS };
    for (const k of PRESET_KEYS) {
        const p = custom.presets?.[k];
        if (!p) continue;
        const ok =
            Number.isInteger(p.barrier) && p.barrier >= 0 && p.barrier <= 8 &&
            Number.isInteger(p.recovery) && p.recovery >= 0 && p.recovery <= 8 &&
            ['mult', 'recover', 'none'].includes(p.recMode) &&
            typeof p.martingale === 'number' && p.martingale >= 1 && p.martingale <= 5 &&
            Number.isInteger(p.maxLosses) && p.maxLosses >= 1 && p.maxLosses <= 20;
        if (!ok) throw new Error(`PREMIUM_RULES: invalid preset ${k}`);
        presets[k] = { barrier: p.barrier, recovery: p.recovery, recMode: p.recMode, martingale: p.martingale, maxLosses: p.maxLosses };
    }
    const bots = { ...DEFAULT_BOTS };
    for (const k of BOT_KEYS) if (custom.bots?.[k]) bots[k] = { ...DEFAULT_BOTS[k], ...custom.bots[k] }; // the website checks every field before use
    return { presets, bots };
};

const floor2 = n => Math.floor(n * 100) / 100;
const round2 = n => Math.round(n * 100) / 100;
const winProb = b => (9 - b) / 10; // DIGITOVER: the last digit is uniformly random
const estRatio = b => 0.93 / winProb(b) - 1; // Deriv pays roughly 7% under fair odds
const num = (v, lo, hi) => (typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi ? v : null);
const int = (v, lo, hi) => (Number.isInteger(v) && v >= lo && v <= hi ? v : null);

/** Validates settings sent by the website. Returns { settings } or { error }. Limits are enforced here, not in the browser. */
const validateSettings = (body, presets = DEFAULT_PRESETS) => {
    const preset = body?.preset;
    let rules;
    if (preset === 'custom') {
        const c = body.custom || {};
        const barrier = int(c.barrier, 0, 8);
        const recovery = int(c.recovery, 0, 8);
        const recMode = ['mult', 'recover', 'none'].includes(c.recMode) ? c.recMode : null;
        const martingale = num(c.martingale, 1, 5);
        if (barrier === null || recovery === null || !recMode || martingale === null) return { error: 'Invalid custom strategy.' };
        rules = { barrier, recovery, recMode, martingale };
    } else if (Object.hasOwn(presets, preset)) {
        const { maxLosses, ...r } = presets[preset];
        rules = r;
    } else return { error: 'Unknown strategy.' };

    const symbol = SYMBOLS.includes(body.symbol) ? body.symbol : null;
    const stake = num(body.stake, 0.35, 50000);
    const takeProfit = num(body.takeProfit, 0.01, 1e7);
    const stopLoss = num(body.stopLoss, 0.01, 1e7);
    const maxLosses = int(body.maxLosses ?? (Object.hasOwn(presets, preset) ? presets[preset].maxLosses : undefined), 1, 20);
    const maxRuns = int(body.maxRuns ?? 0, 0, 10000);
    if (!symbol) return { error: 'Unknown market.' };
    if (stake === null || takeProfit === null || stopLoss === null) return { error: 'Stake, take-profit and stop-loss are required.' };
    if (maxLosses === null || maxRuns === null) return { error: 'Invalid loss or trade limits.' };
    // A stake can never exceed the stop-loss: the server caps it even if the page asks for more
    const maxStake = Math.min(num(body.maxStake, stake, 1e7) ?? stopLoss, stopLoss);
    if (stake > maxStake) return { error: 'Stake must not exceed the stop-loss.' };
    return { settings: { ...rules, preset, symbol, stake, takeProfit, stopLoss, maxStake, maxLosses, maxRuns } };
};

const cleanRatios = r => ({ base: num(r?.base, 0.01, 20), rec: num(r?.rec, 0.01, 20) });

const freshState = s => ({ pl: 0, streak: 0, recLosses: 0, nextStake: s.stake, runs: 0 });

/** Next trade for the current state, or the reason to stop. */
const decide = (s, st, ratios) => {
    if (st.pl >= s.takeProfit) return { stop: 'tp', reason: `Take-profit reached: +${st.pl.toFixed(2)}` };
    if (st.pl <= -s.stopLoss) return { stop: 'sl', reason: `Stop-loss hit: ${st.pl.toFixed(2)}` };
    if (st.streak >= s.maxLosses) return { stop: 'streak', reason: `${st.streak} losses in a row` };
    if (s.maxRuns && st.runs >= s.maxRuns) return { stop: 'runs', reason: `Finished ${st.runs} trades` };
    const recovering = st.streak > 0 && s.recMode !== 'none';
    const barrier = recovering ? s.recovery : s.barrier;
    let want = st.nextStake;
    if (recovering && s.recMode === 'recover') {
        const recR = ratios.rec ?? estRatio(s.recovery);
        const baseR = ratios.base ?? estRatio(s.barrier);
        want = Math.ceil(((st.recLosses + s.stake * baseR) / recR) * 100) / 100;
    }
    const amount = floor2(Math.min(want, s.maxStake, s.stopLoss + st.pl));
    if (amount < 0.35) return { stop: 'sl', reason: 'Not enough room left under the stop-loss for the minimum stake' };
    return { trade: { contract_type: 'DIGITOVER', barrier, amount, symbol: s.symbol, duration: 1, duration_unit: 't', recovery: recovering, capped: amount < want - 0.01 } };
};

/** Applies a settled contract to the state. */
const applyResult = (s, st, { buy_price, profit }) => {
    const won = profit > 0;
    const next = { ...st, runs: st.runs + 1, pl: round2(st.pl + profit) };
    if (won) Object.assign(next, { streak: 0, recLosses: 0, nextStake: s.stake });
    else Object.assign(next, { streak: st.streak + 1, recLosses: round2(st.recLosses - profit), nextStake: s.recMode === 'mult' ? buy_price * s.martingale : s.stake });
    return next;
};

/** Monte Carlo of a session, bounded so it fits a Worker's CPU budget. */
const simulate = (s, capital, ratios, budget = 150000) => {
    const baseR = ratios.base ?? estRatio(s.barrier);
    const recR = ratios.rec ?? estRatio(s.recovery);
    const baseP = winProb(s.barrier);
    const recP = winProb(s.recovery);
    let hit = 0;
    let bust = 0;
    let sum = 0;
    let bustSum = 0;
    let used = 0;
    let sessions = 0;
    const trades = [];
    while (sessions < 4000 && used < budget) {
        let pl = 0;
        let streak = 0;
        let lost = 0;
        let stake = s.stake;
        let n = 0;
        let end = 'open';
        for (; n < 2000; n++) {
            if (pl >= s.takeProfit) {
                end = 'tp';
                break;
            }
            if (pl <= -s.stopLoss || streak >= s.maxLosses) {
                end = 'loss';
                break;
            }
            if (s.maxRuns && n >= s.maxRuns) break;
            const rec = streak > 0 && s.recMode !== 'none';
            let st = s.recMode === 'recover' && rec ? (lost + s.stake * baseR) / recR : s.recMode === 'mult' ? stake : s.stake;
            st = floor2(Math.min(st, s.maxStake, capital + pl, s.stopLoss + pl));
            if (st < 0.35) {
                end = 'loss';
                break;
            }
            if (Math.random() < (rec ? recP : baseP)) {
                pl += st * (rec ? recR : baseR);
                streak = 0;
                lost = 0;
                stake = s.stake;
            } else {
                pl -= st;
                streak++;
                lost += st;
                stake = st * s.martingale;
            }
        }
        used += n + 1;
        sessions++;
        sum += pl;
        trades.push(n);
        if (end === 'tp') hit++;
        else if (end === 'loss' && pl < 0) {
            bust++;
            bustSum += pl;
        }
    }
    trades.sort((a, b) => a - b);
    return { sessions, hit: hit / sessions, bust: bust / sessions, avg: sum / sessions, bustAvg: bust ? bustSum / bust : 0, median: trades[trades.length >> 1] };
};


/**
 * Kapa Premium server (Cloudflare Worker + KV).
 *
 * - Premium is unlocked with a secret code that the owner chooses and can change at any time
 *   (Admin page). The code is checked here, never in the website: a correct code returns a
 *   signed Premium pass, valid until the code changes. Repeated wrong codes lock the caller out.
 * - Identifies traders by asking Deriv which accounts their OAuth access token belongs to.
 *   The token is used for that check only; it is never stored.
 * - Runs the Premium strategies: the website sends each settled contract and receives the
 *   next trade. Sessions are signed (HMAC) so they need no storage, and the Premium pass is
 *   checked again on every decision.
 * - Scans markets itself over Deriv's public WebSocket, simulates session plans, and gives
 *   Premium bot settings to members only.
 * - Takes Premium payments through CinetPay (mobile money and cards), checked with CinetPay's
 *   verification API. A paid buyer receives the Premium code from the owner.
 * - Admin endpoints need ADMIN_SECRET; repeated wrong attempts lock the caller out.
 *
 * Bindings: KV namespace KAPA_KV.
 * Secrets: CINETPAY_APIKEY, CINETPAY_SITE_ID, ADMIN_SECRET, SESSION_KEY, and optionally
 * PREMIUM_CODE (first code, until one is set from Admin) and PREMIUM_RULES.
 * Vars: PRICE_XOF, PLAN_DAYS, CURRENCY, SITE_URL, ALLOWED_ORIGINS, DERIV_API, DERIV_PUBLIC_WS.
 */


const CINETPAY = 'https://api-checkout.cinetpay.com/v2';
const DAY = 24 * 60 * 60 * 1000;
const SESSION_TTL = 6 * 60 * 60 * 1000;
const PASS_TTL = 30 * DAY; // renewed each time the website checks it, while the code is unchanged
const MAX_BODY = 16 * 1024;
const TX_ID = /^kapa_[a-z0-9]+_[a-f0-9]{10}$/;
const ACCOUNT_ID = /^[A-Za-z0-9]{4,32}$/;

const SECURITY_HEADERS = {
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
    'referrer-policy': 'no-referrer',
    'x-frame-options': 'DENY',
    'content-security-policy': "default-src 'none'; frame-ancestors 'none'",
    'strict-transport-security': 'max-age=31536000; includeSubDomains',
};

const json = (body, status = 200) =>
    new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } });
const fail = (status, error) => json({ error }, status);

const corsHeaders = (req, env) => {
    const origin = req.headers.get('origin') || '';
    const allowed = (env.ALLOWED_ORIGINS || '')
        .split(',')
        .map(s => s.trim())
        .filter(Boolean);
    if (!allowed.includes(origin)) return {};
    return {
        'access-control-allow-origin': origin,
        'access-control-allow-headers': 'authorization, content-type, x-admin-secret, x-kapa-pass',
        'access-control-allow-methods': 'GET, POST, OPTIONS',
        'access-control-max-age': '600',
        vary: 'Origin',
    };
};

const enc = new TextEncoder();
const b64url = buf =>
    btoa(String.fromCharCode(...new Uint8Array(buf)))
        .replace(/\+/g, '-')
        .replace(/\//g, '_')
        .replace(/=+$/, '');
const unb64url = s => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/')), c => c.charCodeAt(0));
const sha256 = async text => b64url(await crypto.subtle.digest('SHA-256', enc.encode(text)));

/** Constant-time comparison: hashes both sides first so length differences don't leak either. */
const safeEqual = async (a, b) => {
    if (typeof a !== 'string' || typeof b !== 'string' || !a || !b) return false;
    const [x, y] = await Promise.all([sha256(a), sha256(b)]);
    let diff = 0;
    for (let i = 0; i < x.length; i++) diff |= x.charCodeAt(i) ^ y.charCodeAt(i);
    return diff === 0;
};

// ---------- Signed sessions (no storage needed) ----------
const hmacKey = env =>
    crypto.subtle.importKey('raw', enc.encode(env.SESSION_KEY), { name: 'HMAC', hash: 'SHA-256' }, false, [
        'sign',
        'verify',
    ]);
const signSession = async (env, payload) => {
    const body = b64url(enc.encode(JSON.stringify(payload)));
    const sig = b64url(await crypto.subtle.sign('HMAC', await hmacKey(env), enc.encode(body)));
    return `${body}.${sig}`;
};
const readSession = async (env, token, typ = 'session') => {
    if (typeof token !== 'string' || token.length > 4096 || !/^[\w-]+\.[\w-]+$/.test(token)) return null;
    const [body, sig] = token.split('.');
    try {
        const ok = await crypto.subtle.verify('HMAC', await hmacKey(env), unb64url(sig), enc.encode(body));
        if (!ok) return null;
        const p = JSON.parse(new TextDecoder().decode(unb64url(body)));
        if (!(p?.v === 1 && p.exp > Date.now())) return null;
        if (typ === 'pass') return p.typ === 'pass' && typeof p.ver === 'string' ? p : null;
        return !p.typ && Array.isArray(p.acc) ? p : null; // a pass can never be used as a strategy session
    } catch {
        return null;
    }
};

// ---------- Best-effort rate limiting (per Worker instance) ----------
const buckets = new Map();
const rateLimited = (key, limit, windowMs = 60000) => {
    const now = Date.now();
    const b = buckets.get(key);
    if (!b || now - b.start > windowMs) {
        buckets.set(key, { start: now, count: 1 });
        if (buckets.size > 5000) buckets.clear();
        return false;
    }
    b.count++;
    return b.count > limit;
};
// The visitor's address as set by the host (Cloudflare or Netlify); never taken from headers a visitor can forge
const clientIp = req => req.headers.get('cf-connecting-ip') || req.headers.get('x-nf-client-connection-ip') || 'unknown';

// ---------- Deriv identity (cached briefly, keyed by a hash of the token) ----------
const derivAccounts = async (req, env) => {
    const auth = req.headers.get('authorization') || '';
    if (!/^Bearer [\w.~+/=-]{10,4096}$/.test(auth)) return null;
    const cacheKey = new Request(`https://kapa-identity.internal/${await sha256(auth)}`);
    const cache = typeof caches !== 'undefined' ? caches.default : null;
    const hit = cache && (await cache.match(cacheKey));
    if (hit) return hit.json();
    const res = await fetch(`${env.DERIV_API || 'https://api.derivws.com'}/trading/v1/options/accounts`, {
        headers: { authorization: auth, accept: 'application/json' },
    });
    if (!res.ok) return null;
    const body = await res.json().catch(() => ({}));
    const ids = (Array.isArray(body?.data) ? body.data : [])
        .map(a => String(a.account_id || ''))
        .filter(id => ACCOUNT_ID.test(id));
    if (!ids.length) return null;
    if (cache)
        await cache.put(cacheKey, new Response(JSON.stringify(ids), { headers: { 'cache-control': 'max-age=120' } }));
    return ids;
};

// ---------- Premium code ----------
// Codes ignore spaces, dashes and letter case, so a code typed on a phone still matches.
const normalizeCode = code => (typeof code === 'string' ? code.replace(/[\s-]+/g, '').toUpperCase() : '');
const CODE_OK = /^[A-Z0-9_.@#!*+=]{8,64}$/;

const codeHash = async (env, code) => {
    const key = await crypto.subtle.importKey(
        'raw',
        enc.encode(env.SESSION_KEY),
        { name: 'HMAC', hash: 'SHA-256' },
        false,
        ['sign']
    );
    return b64url(await crypto.subtle.sign('HMAC', key, enc.encode(`premium-code:${code}`)));
};

/** The current code: the one set from Admin, otherwise the PREMIUM_CODE secret. Only its hash is kept. */
const currentCode = async env => {
    const saved = await env.KAPA_KV.get('premium:code', 'json');
    if (saved?.h && saved?.ver) return { ...saved, source: 'admin' };
    const first = normalizeCode(env.PREMIUM_CODE || '');
    if (CODE_OK.test(first)) {
        const h = await codeHash(env, first);
        return { h, ver: `secret-${h.slice(0, 12)}`, source: 'secret' };
    }
    return null;
};

const issuePass = (env, ver) => signSession(env, { v: 1, typ: 'pass', ver, exp: Date.now() + PASS_TTL });

/** A Premium pass is valid while it is signed by this server, not expired, and made for the current code. */
const readPass = async (env, req) => {
    if (!env.SESSION_KEY || env.SESSION_KEY.length < 32) return null;
    const p = await readSession(env, req.headers.get('x-kapa-pass') || '', 'pass');
    if (!p) return null;
    const code = await currentCode(env);
    return code && p.ver === code.ver ? p : null;
};

const cinetpayCheck = async (env, transactionId) => {
    const res = await fetch(`${CINETPAY}/payment/check`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
            apikey: env.CINETPAY_APIKEY,
            site_id: env.CINETPAY_SITE_ID,
            transaction_id: transactionId,
        }),
    });
    return res.json().catch(() => ({}));
};

/** Verifies a payment with CinetPay and records the result. Safe to call repeatedly. The owner then sends the code. */
const settle = async (env, transactionId) => {
    const tx = await env.KAPA_KV.get(`tx:${transactionId}`, 'json');
    if (!tx) return { status: 'unknown' };
    if (tx.status === 'paid' || tx.status === 'failed') return tx;
    const check = await cinetpayCheck(env, transactionId);
    const status = check?.data?.status;
    const paidAmount = Number(check?.data?.amount);
    if (
        check?.code === '00' &&
        status === 'ACCEPTED' &&
        paidAmount >= tx.amount &&
        (!check?.data?.currency || check.data.currency === tx.currency)
    ) {
        Object.assign(tx, {
            status: 'paid',
            paidAt: Date.now(),
            method: String(check.data.payment_method || '').slice(0, 32) || null,
        });
    } else if (status === 'REFUSED' || status === 'CANCELED') {
        Object.assign(tx, { status: 'failed', reason: status });
    } else {
        return tx; // still pending: nothing to write
    }
    await env.KAPA_KV.put(`tx:${transactionId}`, JSON.stringify(tx));
    return tx;
};

const listPrefix = async (env, prefix) => {
    const out = [];
    let cursor;
    do {
        const page = await env.KAPA_KV.list({ prefix, cursor });
        for (const k of page.keys)
            out.push({ key: k.name.slice(prefix.length), value: await env.KAPA_KV.get(k.name, 'json') });
        cursor = page.list_complete ? undefined : page.cursor;
    } while (cursor);
    return out;
};

const readJson = async req => {
    const len = Number(req.headers.get('content-length') || 0);
    if (len > MAX_BODY) return null;
    const text = await req.text();
    if (text.length > MAX_BODY) return null;
    try {
        return text ? JSON.parse(text) : {};
    } catch {
        return null;
    }
};

// ---------- Deriv public WebSocket (prices and ticks need no login) ----------
const openDerivSocket = async env => {
    if (env.OPEN_SOCKET) return env.OPEN_SOCKET(); // test hook; never set in production
    const url = env.DERIV_PUBLIC_WS || 'https://api.derivws.com/trading/v1/options/ws/public';
    if (typeof WebSocketPair === 'undefined' && typeof WebSocket !== 'undefined') {
        // Node (Netlify): a standard WebSocket client
        const ws = new WebSocket(url.replace(/^http/, 'ws'));
        await new Promise((resolve, reject) => {
            const timer = setTimeout(() => reject(new Error('Deriv market data is unavailable')), 6000);
            ws.addEventListener('open', () => (clearTimeout(timer), resolve()));
            ws.addEventListener('error', () => (clearTimeout(timer), reject(new Error('Deriv market data is unavailable'))));
        });
        return ws;
    }
    // Cloudflare Workers
    const res = await fetch(url, { headers: { Upgrade: 'websocket' } });
    const ws = res.webSocket;
    if (!ws) throw new Error('Deriv market data is unavailable');
    ws.accept();
    return ws;
};

/** Sends several requests over one socket and returns the answers in order (null for failures). */
const derivBatch = async (env, requests, timeoutMs = 8000) => {
    const ws = await openDerivSocket(env);
    const results = new Array(requests.length).fill(null);
    let pending = requests.length;
    await new Promise(resolve => {
        const timer = setTimeout(resolve, timeoutMs);
        ws.addEventListener('message', ev => {
            let msg;
            try {
                msg = JSON.parse(typeof ev.data === 'string' ? ev.data : new TextDecoder().decode(ev.data));
            } catch {
                return;
            }
            const i = Number(msg.req_id) - 1;
            if (i >= 0 && i < results.length && results[i] === null) {
                results[i] = msg.error ? { error: msg.error } : msg;
                if (--pending === 0) {
                    clearTimeout(timer);
                    resolve();
                }
            }
        });
        requests.forEach((r, i) => ws.send(JSON.stringify({ ...r, req_id: i + 1 })));
    });
    try {
        ws.close(1000, 'done');
    } catch {
        /* already closed */
    }
    return results;
};

const SCAN_SYMBOLS = ['R_10', 'R_25', 'R_50', 'R_75', 'R_100'];
const PIP = { R_10: 3, R_25: 3, R_50: 4, R_75: 4, R_100: 2 };
const quote = (sym, barrier, currency) => ({
    proposal: 1,
    amount: 10,
    basis: 'stake',
    contract_type: 'DIGITOVER',
    currency,
    duration: 1,
    duration_unit: 't',
    underlying_symbol: sym,
    barrier: String(barrier),
});
const ratioOf = r =>
    r?.proposal ? (Number(r.proposal.payout) - Number(r.proposal.ask_price)) / Number(r.proposal.ask_price) : null;

/** Ranks markets for a Premium strategy with Deriv's live prices and the last 100 ticks. */
const scan = async (env, body, rules) => {
    const { presets } = rules;
    const preset = Object.hasOwn(presets, body?.preset) ? body.preset : 'martingale';
    const r0 = presets[preset];
    const cur = /^[A-Z]{3}$/.test(body?.currency || '') ? body.currency : 'USD';
    const symbols = Array.isArray(body?.symbols)
        ? body.symbols.filter(sym => SCAN_SYMBOLS.includes(sym)).slice(0, 5)
        : SCAN_SYMBOLS;
    const reqs = [];
    symbols.forEach(sym => {
        reqs.push({ ticks_history: sym, count: 100, end: 'latest', style: 'ticks' });
        reqs.push(quote(sym, r0.barrier, cur));
        if (r0.recMode !== 'none') reqs.push(quote(sym, r0.recovery, cur));
    });
    let res;
    try {
        res = await derivBatch(env, reqs);
    } catch {
        return fail(503, 'Deriv market data is unavailable. Try again shortly.');
    }
    const per = r0.recMode !== 'none' ? 3 : 2;
    const rows = symbols
        .map((sym, i) => {
            const [hist, base, rec] = res.slice(i * per, i * per + per);
            const r = ratioOf(base);
            if (r === null) return null;
            const pip = hist?.pip_size ?? PIP[sym] ?? 2;
            const digits = (hist?.history?.prices || []).map(x => {
                const t = Number(x).toFixed(pip);
                return +t[t.length - 1];
            });
            const p = winProb(r0.barrier);
            return {
                symbol: sym,
                barrier: r0.barrier,
                recovery: r0.recMode !== 'none' ? r0.recovery : null,
                win_chance: p,
                payout: r,
                recovery_payout: per === 3 ? ratioOf(rec) : null,
                expected: p * (1 + r) - 1,
                recent: digits.length ? digits.filter(d => d > r0.barrier).length / digits.length : null,
                recent_ticks: digits.length,
            };
        })
        .filter(Boolean)
        .sort((a, b) => b.expected - a.expected);
    return json({ preset, rows });
};

// ---------- Routes ----------
const handle = async (req, env) => {
    const url = new URL(req.url);
    const path = url.pathname.replace(/\/+$/, '') || '/';
    const ip = clientIp(req);
    const price = Number(env.PRICE_XOF || 0);
    const days = Number(env.PLAN_DAYS || 30);
    const currency = env.CURRENCY || 'XOF';
    if (rateLimited(`all:${ip}`, 240)) return fail(429, 'Too many requests. Wait a minute and try again.');
    let loaded;
    const rules = () => (loaded ??= loadRules(env)); // only Premium routes need them; payments keep working if they're misconfigured

    if (req.method === 'GET' && path === '/')
        return json({ service: 'Kapa Premium server', status: 'online', premium_code: Boolean(await currentCode(env).catch(() => null)) });

    if (req.method === 'GET' && path === '/plan')
        return json({
            price,
            currency,
            days,
            configured: Boolean(env.CINETPAY_APIKEY && env.CINETPAY_SITE_ID && price > 0),
        });

    // CinetPay calls this after each payment attempt; only the transaction id is used, then verified with CinetPay
    if (path === '/cinetpay/notify') {
        if (req.method !== 'POST') return new Response('OK');
        const form = await req.formData().catch(() => null);
        const id = String(form?.get('cpm_trans_id') || '');
        if (TX_ID.test(id) && !rateLimited(`notify:${id}`, 10)) await settle(env, id);
        return new Response('OK');
    }

    // Where CinetPay sends the buyer back (GET or POST): settle, then return to the site
    if (path === '/return') {
        const id = url.searchParams.get('tx') || '';
        const valid = TX_ID.test(id);
        if (valid) await settle(env, id);
        return new Response(null, {
            status: 303,
            headers: { location: `${env.SITE_URL}${valid ? `?premium_tx=${id}` : ''}#kapa_ai` },
        });
    }

    if (path.startsWith('/admin/')) {
        if (rateLimited(`admin:${ip}`, 20)) return fail(429, 'Too many attempts. Wait a minute.');
        const lockKey = `adminfail:${await sha256(ip)}`;
        const fails = Number((await env.KAPA_KV.get(lockKey)) || 0);
        if (fails >= 10) return fail(429, 'Too many wrong attempts. Try again in an hour.');
        if (
            !(
                env.ADMIN_SECRET &&
                env.ADMIN_SECRET.length >= 20 &&
                (await safeEqual(req.headers.get('x-admin-secret') || '', env.ADMIN_SECRET))
            )
        ) {
            await env.KAPA_KV.put(lockKey, String(fails + 1), { expirationTtl: 3600 });
            return fail(401, 'Wrong admin secret');
        }
        if (req.method === 'GET' && path === '/admin/payments') return json({ payments: await listPrefix(env, 'tx:') });
        if (req.method === 'GET' && path === '/admin/code') {
            const code = env.SESSION_KEY && env.SESSION_KEY.length >= 32 ? await currentCode(env) : null;
            return json({
                set: Boolean(code),
                source: code?.source ?? null,
                updatedAt: code?.updatedAt ?? null,
                ready: Boolean(env.SESSION_KEY && env.SESSION_KEY.length >= 32),
            });
        }
        // Setting a new code signs everyone out of Premium; they need the new code
        if (req.method === 'POST' && path === '/admin/code') {
            if (!env.SESSION_KEY || env.SESSION_KEY.length < 32)
                return fail(503, 'Set SESSION_KEY on the server first');
            const body = await readJson(req);
            const code = normalizeCode(body?.code);
            if (!CODE_OK.test(code))
                return fail(
                    400,
                    'The code needs 8 to 64 letters, digits or _ . @ # ! * + = (spaces and dashes are ignored)'
                );
            const ver = b64url(crypto.getRandomValues(new Uint8Array(12)));
            const saved = { h: await codeHash(env, code), ver, updatedAt: Date.now() };
            await env.KAPA_KV.put('premium:code', JSON.stringify(saved));
            return json({ set: true, source: 'admin', updatedAt: saved.updatedAt });
        }
        return fail(404, 'Not found');
    }

    // Session plan: free for everyone (it shows the risk before anyone pays), CPU-bounded
    if (req.method === 'POST' && path === '/plan/simulate') {
        if (rateLimited(`sim:${ip}`, 30)) return fail(429, 'Too many simulations. Wait a minute.');
        const body = await readJson(req);
        const v = validateSettings(body, rules().presets);
        if (v.error) return fail(400, v.error);
        const s = v.settings;
        const capital = Number.isFinite(body.capital) && body.capital > 0 ? Math.min(body.capital, 1e8) : 1000;
        return json(simulate(s, capital, cleanRatios(body.ratios)));
    }

    // ----- Premium code: unlock and check (no Deriv login needed) -----
    if (req.method === 'POST' && path === '/premium/unlock') {
        if (rateLimited(`unlock:${ip}`, 10)) return fail(429, 'Too many attempts. Wait a minute.');
        const lockKey = `codefail:${await sha256(ip)}`;
        const fails = Number((await env.KAPA_KV.get(lockKey)) || 0);
        if (fails >= 10) return fail(429, 'Too many wrong codes. Try again in an hour.');
        if (!env.SESSION_KEY || env.SESSION_KEY.length < 32) return fail(503, 'Premium is not set up yet');
        const code = await currentCode(env);
        if (!code) return fail(503, 'Premium is not set up yet');
        const body = await readJson(req);
        const given = normalizeCode(body?.code);
        if (!CODE_OK.test(given) || !(await safeEqual(await codeHash(env, given), code.h))) {
            await env.KAPA_KV.put(lockKey, String(fails + 1), { expirationTtl: 3600 });
            return fail(401, 'Wrong code. Check it and try again.');
        }
        return json({ status: 'active', pass: await issuePass(env, code.ver), expiresAt: Date.now() + PASS_TTL });
    }

    if (req.method === 'GET' && path === '/premium/status') {
        const p = await readPass(env, req);
        if (!p) return json({ status: 'inactive' });
        // a pass in use is renewed, so a device stays unlocked until the code changes
        return json({ status: 'active', pass: await issuePass(env, p.ver), expiresAt: Date.now() + PASS_TTL });
    }

    const pass = () => readPass(env, req);

    // Premium tools that don't trade: need the pass only
    if (req.method === 'POST' && path === '/scan') {
        if (!(await pass())) return fail(402, 'This is part of KAPA AI Premium.');
        if (rateLimited(`scan:${ip}`, 10)) return fail(429, 'Too many scans. Wait a minute.');
        return scan(env, await readJson(req), rules());
    }
    const bot = path.match(/^\/bots\/([a-z0-9-]{1,40})$/);
    if (req.method === 'GET' && bot) {
        if (!(await pass())) return fail(402, 'This is part of KAPA AI Premium.');
        const { bots } = rules();
        const data = Object.hasOwn(bots, bot[1]) ? bots[bot[1]] : null;
        return data ? json({ id: bot[1], data }) : fail(404, 'Bot not found');
    }

    // Everything below needs a signed-in Deriv user
    const ids = await derivAccounts(req, env);
    if (!ids) return fail(401, 'Log in with Deriv first');

    if (req.method === 'POST' && path === '/checkout') {
        if (!(env.CINETPAY_APIKEY && env.CINETPAY_SITE_ID && price > 0))
            return fail(503, 'Payments are not set up yet');
        if (rateLimited(`checkout:${ids[0]}`, 5, 10 * 60000))
            return fail(429, 'Too many payment attempts. Wait a few minutes.');
        const transactionId = `kapa_${Date.now().toString(36)}_${[...crypto.getRandomValues(new Uint8Array(5))].map(x => x.toString(16).padStart(2, '0')).join('')}`;
        const tx = { status: 'pending', accounts: ids, amount: price, currency, days, createdAt: Date.now() };
        await env.KAPA_KV.put(`tx:${transactionId}`, JSON.stringify(tx));
        const res = await fetch(`${CINETPAY}/payment`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({
                apikey: env.CINETPAY_APIKEY,
                site_id: env.CINETPAY_SITE_ID,
                transaction_id: transactionId,
                amount: price,
                currency,
                description: `Kapa Trader Premium ${days} days`,
                notify_url: `${url.origin}/cinetpay/notify`,
                return_url: `${url.origin}/return?tx=${transactionId}`, // CinetPay may POST here; GitHub Pages can't accept POST
                channels: 'ALL',
                lang: 'FR',
            }),
        });
        const body = await res.json().catch(() => ({}));
        if (
            body?.code !== '201' ||
            !body?.data?.payment_url ||
            !/^https:\/\/[\w.-]*cinetpay\.com\//.test(body.data.payment_url)
        ) {
            await env.KAPA_KV.put(
                `tx:${transactionId}`,
                JSON.stringify({ ...tx, status: 'failed', reason: 'init failed' })
            );
            return fail(502, 'The payment could not be started. Try again later.');
        }
        return json({ transaction_id: transactionId, payment_url: body.data.payment_url });
    }

    if (req.method === 'GET' && path === '/checkout/status') {
        const id = url.searchParams.get('tx') || '';
        if (!TX_ID.test(id)) return fail(404, 'Payment not found');
        const tx = await env.KAPA_KV.get(`tx:${id}`, 'json');
        if (!tx || !tx.accounts.some(a => ids.includes(a))) return fail(404, 'Payment not found');
        const settled = await settle(env, id);
        return json({ status: settled.status, expiresAt: settled.expiresAt });
    }

    // ----- Premium strategy sessions: Deriv login and a valid Premium pass -----
    if (!(await pass())) return fail(402, 'This is part of KAPA AI Premium.');
    if (rateLimited(`premium:${ids[0]}`, 120)) return fail(429, 'Too many requests. Wait a minute.');

    if (req.method === 'POST' && path === '/session/start') {
        if (!env.SESSION_KEY || env.SESSION_KEY.length < 32) return fail(503, 'Strategy sessions are not set up yet');
        const body = await readJson(req);
        const v = validateSettings(body, rules().presets);
        if (v.error) return fail(400, v.error);
        const s = v.settings;
        const ratios = cleanRatios(body.ratios);
        const st = freshState(s);
        const decision = decide(s, st, ratios);
        const token = await signSession(env, {
            v: 1,
            acc: ids,
            s,
            st,
            r: ratios,
            last: null,
            d: decision,
            exp: Date.now() + SESSION_TTL,
        });
        return json({ session: token, decision });
    }

    if (req.method === 'POST' && path === '/session/next') {
        if (!env.SESSION_KEY) return fail(503, 'Strategy sessions are not set up yet');
        const body = await readJson(req);
        const p = await readSession(env, body?.session);
        if (!p || !p.acc.some(a => ids.includes(a)))
            return fail(400, 'This strategy session has expired. Start KAPA AI again.');
        const r = body.result || {};
        const contractId = Number(r.contract_id);
        const buy = Number(r.buy_price);
        const profit = Number(r.profit);
        if (!Number.isSafeInteger(contractId) || contractId <= 0) return fail(400, 'Invalid contract.');
        if (p.last === contractId) return json({ session: body.session, decision: p.d }); // the same result sent twice
        if (!(buy >= 0.35 && buy <= p.s.maxStake * 1.01 + 0.01) || !(profit >= -buy - 0.01 && profit <= buy * 20))
            return fail(400, 'Invalid contract result.');
        const ratios = {
            ...p.r,
            ...Object.fromEntries(Object.entries(cleanRatios(body.ratios)).filter(([, x]) => x !== null)),
        };
        const st = applyResult(p.s, p.st, { buy_price: buy, profit });
        const decision = decide(p.s, st, ratios);
        const token = await signSession(env, { ...p, st, r: ratios, last: contractId, d: decision });
        return json({ session: token, decision, state: { pl: st.pl, runs: st.runs, streak: st.streak } });
    }

    return fail(404, 'Not found');
};

export default {
    async fetch(req, env) {
        const cors = corsHeaders(req, env);
        if (req.method === 'OPTIONS')
            return new Response(null, { status: 204, headers: { ...cors, ...SECURITY_HEADERS } });
        let res;
        try {
            res = await handle(req, env);
        } catch {
            res = fail(500, 'Server error');
        }
        const out = new Response(res.body, res);
        Object.entries({ ...SECURITY_HEADERS, ...cors }).forEach(([k, v]) => out.headers.set(k, v));
        return out;
    },
};

